            daily_rate=car.daily_rate,
            total_price=car.total_price,
            status="confirmed",
            insurance_included=car.insurance_included,
            booked_at=self.now,
        )
        self.car_rentals[rental_id] = rental

        return {
            "status": "confirmed",
            "rental_id": rental_id,
            "car_id": car.car_id,
            "company": car.company,
            "car_class": car.car_class,
            "total_price": car.total_price,
